// ¿Ya se pagó el celular este mes? Mira los movimientos del mes en Notion: un gasto «Celular Aleja» / «Celular amor» o «Celular Carlos».
// Así el aviso de arriba de Armoni se quita solo, sin importar si el gasto lo registró el correo del pago (PSE), el otro celular o la app.
const clave = (n) => 'property_' + String(n).toLowerCase().replace(/\s+/g, '_');
const txt = (a) => ((a || []).map(t => t.plain_text).join('') || '').trim();
const leer = (it, nombre, tipo) => {
  const pr = it.properties && it.properties[nombre];
  if (pr) {
    if (tipo === 'titulo') return txt(pr.title);
    if (tipo === 'fecha') return pr.date && pr.date.start ? pr.date.start.slice(0, 10) : null;
    if (tipo === 'select') return pr.select ? pr.select.name : null;
  }
  let v = it[clave(nombre)];
  if (v === undefined && tipo === 'titulo') v = it.name;
  if (v === undefined || v === null || v === '') return null;
  if (tipo === 'fecha') { const s = typeof v === 'object' ? (v.start || '') : String(v); return s ? s.slice(0, 10) : null; }
  return String(v);
};
let q = {}, esWeb = false;
try { const w = $('Webhook').first(); if (w) { esWeb = true; q = w.json.query || {}; } } catch (e) {}
if (esWeb && q.token !== 'mercado-7d41c2a9e05b') return [{ json: { web: true, ok: false, error: 'token' } }];
const ahoraCo = new Date(Date.now() - 5 * 3600 * 1000), mes = ahoraCo.toISOString().slice(0, 7), hoy = ahoraCo.toISOString().slice(0, 10), dia = ahoraCo.getUTCDate();
const pagados = { aleja: false, carlos: false };
for (const it of $input.all().map(i => i.json)) {
  const f = leer(it, 'Fecha', 'fecha') || '', c = (leer(it, 'Concepto', 'titulo') || '').toLowerCase();
  if (!f.startsWith(mes) || leer(it, 'Tipo', 'select') === 'Ingreso' || !/celular|claro|comcel/.test(c)) continue;
  if (/aleja/.test(c)) pagados.aleja = true;
  else if (/carlos|amor/.test(c)) pagados.carlos = true;   // «celular amor» es el de Carlos
  else {   // el correo PSE lo guarda solo como «Celular» (siempre lo paga Alejandra): se sabe de quién es por el día. Del 1 al 14 es el de Aleja (se paga del 1 al 5); del 15 en adelante, el de Carlos («celular amor», se paga del 15 al 23)
    if (Number(f.slice(8, 10)) <= 14) pagados.aleja = true; else pagados.carlos = true;
  }
}

// aviso al celular (solo cuando corre solo, no cuando lo pide la app): en los dos últimos días de cada ventana, a las 8 am y a las 5 pm, hasta que se pague
// Aleja: del 1 al 5 · Carlos («celular amor»): del 15 al 23
const VENT = { aleja: { nombre: 'Aleja', hasta: 5, desde: 1 }, carlos: { nombre: 'Carlos (amor)', hasta: 23, desde: 15 } };
let enviado = false;
if (!esWeb) {
  const sd = $getWorkflowStaticData('global');
  const franja = ahoraCo.getUTCHours() < 12 ? 'am' : 'pm', clave = hoy + ' ' + franja;
  const faltan = Object.keys(VENT).filter(k => !pagados[k] && dia >= VENT[k].desde && dia >= VENT[k].hasta - 1 && dia <= VENT[k].hasta);
  if (faltan.length && !(sd.celAvisos && sd.celAvisos[clave])) {
    const hoyVence = faltan.some(k => dia === VENT[k].hasta);
    const quien = faltan.map(k => VENT[k].nombre);
    const texto = quien.length > 1 ? quien.join(' y ') : quien[0];
    try {
      await this.helpers.httpRequest({ method: 'POST', url: 'http://localhost:5678/webhook/push-enviar', body: { token: 'mercado-7d41c2a9e05b', title: hoyVence ? '⚠️ Hoy vence el celular' : '📱 Mañana vence el celular', body: 'Hace falta pagar el celular de ' + texto + '. Toca para pagar.', url: './?ver=pagar', tag: 'celulares' }, json: true, timeout: 15000 });
      enviado = true;
      const m = sd.celAvisos || {}; m[clave] = 1; Object.keys(m).filter(x => x.slice(0, 10) < hoy).forEach(x => delete m[x]); sd.celAvisos = m;
    } catch (e) {}
  }
}
return [{ json: { web: esWeb, ok: true, mes, pagados, enviado } }];
